svg.script:
(function(){
  var root = document.querySelector('.a6p2-root');
  if(!root) return;
  function Q(s){ return root.querySelector(s); }
  function QA(s){ return root.querySelectorAll(s); }

  var statusEl = Q('#a6p2-status');
  var liveEl = Q('#a6p2-live');
  var tip = Q('#a6p2-tip');
  var pulseBtn = Q('#a6p2-btn-pulse');
  var dimBtn = Q('#a6p2-btn-dim');
  var timers = [];
  var playing = false;
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e) { reduce = false; }

  var domains = ['motor','sens','sensor','comp'];
  var labels = {
    motor: { title: 'Porta motora', status: 'Motor aceso · súbito e transitório', tip1: 'Motor', tip2: 'Clonia, tônico, atonia — o óbvio, não o único.', stroke: 'var(--a6p2-motor, #F87171)' },
    sens: { title: 'Porta sensitiva', status: 'Sensitivo aceso · dormência que some', tip1: 'Sensitivo', tip2: 'Parestesia/dormência súbita que retorna ao basal.', stroke: 'var(--a6p2-sens, #2DD4BF)' },
    sensor: { title: 'Porta sensorial', status: 'Sensorial aceso · aura transitória', tip1: 'Sensorial', tip2: 'Visual, auditivo ou olfatório que acende e apaga.', stroke: 'var(--a6p2-sensor, #A78BFA)' },
    comp: { title: 'Porta comportamental', status: 'Comportamental aceso · confusão que retoma', tip1: 'Comportamental', tip2: 'Voz, confusão, desconexão — não apague do DDx.', stroke: 'var(--a6p2-comp, #FBBF24)' }
  };

  function clearTimers(){
    for(var i=0;i<timers.length;i++) clearTimeout(timers[i]);
    timers = [];
    playing = false;
    root.setAttribute('data-playing','0');
  }

  function setActive(domain, dim){
    if(dim){
      root.setAttribute('data-dim','1');
      root.removeAttribute('data-active');
      if(statusEl){
        statusEl.textContent = 'Apagado · o transitório é o ensino';
        statusEl.setAttribute('fill','var(--a6p2-muted, #94A3B8)');
      }
      if(liveEl) liveEl.textContent = 'Todos os domínios apagados. O apagar é parte do padrão súbito e transitório.';
      return;
    }
    root.setAttribute('data-dim','0');
    if(!domain){
      root.removeAttribute('data-active');
      if(statusEl){
        statusEl.textContent = 'Em repouso · portas disponíveis';
        statusEl.setAttribute('fill','var(--a6p2-soft, #B8C0CC)');
      }
      if(liveEl) liveEl.textContent = 'Nenhum domínio ativo. Qualquer porta pode abrir.';
      return;
    }
    root.setAttribute('data-active', domain);
    var L = labels[domain];
    if(statusEl && L){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl && L) liveEl.textContent = L.title + '. ' + L.tip2;
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p2-tip-t1');
    var t2el = Q('#a6p2-tip-t2');
    var bg = Q('#a6p2-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p2-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 280, h = 58, off = 14;
    var x = p.x + off, y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 580) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
    tip.setAttribute('opacity','1');
    tip.setAttribute('aria-hidden','false');
  }

  function hideTip(){
    if(!tip) return;
    tip.setAttribute('opacity','0');
    tip.setAttribute('aria-hidden','true');
  }

  function pulseSequence(){
    clearTimers();
    playing = true;
    root.setAttribute('data-playing','1');
    setActive(null, false);
    var i = 0;
    var stepOn = reduce ? 500 : 700;
    var stepOff = reduce ? 280 : 420;
    function next(){
      if(i >= domains.length){
        timers.push(setTimeout(function(){
          setActive(null, true);
          timers.push(setTimeout(function(){
            setActive(null, false);
            playing = false;
            root.setAttribute('data-playing','0');
            if(statusEl){
              statusEl.textContent = 'Ciclo completo · inclusão, não exclusão';
              statusEl.setAttribute('fill','var(--a6p2-gold, #FBBF24)');
            }
            if(liveEl) liveEl.textContent = 'Quatro portas acenderam e apagaram. Qualquer domínio abre o DDx de epilepsia.';
          }, reduce ? 500 : 700));
        }, stepOff));
        return;
      }
      var d = domains[i];
      setActive(d, false);
      i++;
      timers.push(setTimeout(function(){
        setActive(null, false);
        timers.push(setTimeout(next, stepOff));
      }, stepOn));
    }
    next();
  }

  function bindDoor(el){
    if(!el) return;
    var domain = el.getAttribute('data-domain');
    var L = labels[domain];
    function activate(ev){
      clearTimers();
      setActive(domain, false);
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 80;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 20;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      setActive(domain, false);
      showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1') showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
      if(root.getAttribute('data-active')===domain && !playing){
        /* keep last pin if clicked; only clear on leave if not pinned via click flag */
      }
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      if(playing) return;
      setActive(domain, false);
      var b = el.getBoundingClientRect();
      showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing) hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  var doorIds = ['#a6p2-door-motor','#a6p2-door-sens','#a6p2-door-sensor','#a6p2-door-comp'];
  for(var di=0; di<doorIds.length; di++) bindDoor(Q(doorIds[di]));

  if(pulseBtn){
    pulseBtn.addEventListener('click', pulseSequence);
    pulseBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); pulseSequence(); }
    });
  }
  if(dimBtn){
    dimBtn.addEventListener('click', function(){ clearTimers(); setActive(null, true); hideTip(); });
    dimBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); clearTimers(); setActive(null, true); hideTip(); }
    });
  }

  var chips = {
    age: ['Qualquer idade', 'Lactente ao idoso: o mantra não tem teto etário.', 'var(--a6p2-indigo, #818CF8)'],
    first: ['Primeiro evento', 'A porta já existe no primeiro evento típico.', 'var(--a6p2-cyan, #22D3EE)'],
    rec: ['Recorrência', 'Reforça a hipótese; não é pré-requisito para abrir.', 'var(--a6p2-indigo, #818CF8)'],
    ddx: ['DDx amplo', 'Síncope, psicose, confusão: inclusão, não exclusão.', 'var(--a6p2-gold, #FBBF24)']
  };

  function bindChip(id, key){
    var el = Q(id);
    if(!el) return;
    var data = chips[key];
    function go(ev){
      var cx = (ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      showTip(cx, cy, data[0], data[1], data[2]);
      if(liveEl) liveEl.textContent = data[0] + '. ' + data[1];
    }
    el.addEventListener('mouseenter', go);
    el.addEventListener('mousemove', function(ev){ if(tip && tip.getAttribute('opacity')==='1') go(ev); });
    el.addEventListener('mouseleave', hideTip);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      showTip(b.left + b.width/2, b.top + b.height/2, data[0], data[1], data[2]);
    });
    el.addEventListener('blur', hideTip);
    el.addEventListener('click', go);
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); go(ev); }
    });
  }
  bindChip('#a6p2-chip-age','age');
  bindChip('#a6p2-chip-first','first');
  bindChip('#a6p2-chip-rec','rec');
  bindChip('#a6p2-chip-ddx','ddx');

  root.addEventListener('click', function(ev){
    var t = ev.target;
    var doors = Q('#a6p2-doors');
    var chipsG = Q('#a6p2-chips');
    var ctrls = Q('#a6p2-controls');
    if(doors && doors.contains(t)) return;
    if(chipsG && chipsG.contains(t)) return;
    if(ctrls && ctrls.contains(t)) return;
    hideTip();
  });

  setActive(null, false);
})();
